ALTER TABLE USER_POST
    ADD CONSTRAINT FK_USER_POST_BRAND
        FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND (ID);

ALTER TABLE IMPORT_USERS_DATA
    ADD CONSTRAINT FK_IMPORT_USERS_DATA_BRAND
        FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND (ID);

ALTER TABLE REALM_BRAND
    ADD COLUMN DEFAULT_REALM_UNIQ VARCHAR(64)
        GENERATED ALWAYS AS (CASE WHEN IS_DEFAULT = 1 THEN REALM_ID ELSE NULL END) VIRTUAL;
